import urllib.request, json
req = urllib.request.Request('https://www.sefaria.org/api/v3/texts/Tosafot_on_Shabbat.133a?version=all', headers={'User-Agent': 'Mozilla/5.0'})
try:
    with urllib.request.urlopen(req) as resp:
